class MainActivity : ComponentActivity() {
    private val vm by viewModels<AppViewModel>()

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent { RivanApp(vm) }
    }
}

enum class Section(val label:String, val icon:ImageVector) {
    HOME("Home", Icons.Default.Home), CENTERS("Centers", Icons.Default.Business), WORK("Work", Icons.Default.Description), FINANCE("Finance", Icons.Default.Payments), HR("HR", Icons.Default.People), SYSTEM("System", Icons.Default.Settings)
}

@Composable
fun RivanApp(vm:AppViewModel) {
    val data by vm.data.collectAsStateWithLifecycle()
    var dark by rememberSaveable { mutableStateOf(data.branding.theme == "dark") }
    LaunchedEffect(data.branding.theme) { dark = data.branding.theme == "dark" }
    MaterialTheme(colorScheme = if(dark) darkColorScheme(primary=Color(0xFF48D597), secondary=Color(0xFF7BDCB5)) else lightColorScheme(primary=Color(0xFF087F45), secondary=Color(0xFF0F9D68))) {
        Surface(Modifier.fillMaxSize()) {
            AnimatedContent(targetState=data.auth.loggedIn, transitionSpec={ fadeIn()+scaleIn(initialScale=.98f) togetherWith fadeOut() }, label="auth") { logged ->
                if (!logged) LoginScreen(vm) else MainShell(vm, dark) { dark=it }
            }
        }
    }
}

@Composable
fun LoginScreen(vm:AppViewModel) {
    val context=LocalContext.current
    var role by rememberSaveable { mutableStateOf("admin") }
    var id by rememberSaveable { mutableStateOf("ADMIN-01") }
    var pass by rememberSaveable { mutableStateOf("1234") }
    var error by remember { mutableStateOf("") }
    Box(Modifier.fillMaxSize().background(Brush.linearGradient(listOf(MaterialTheme.colorScheme.primary.copy(.18f),MaterialTheme.colorScheme.background,MaterialTheme.colorScheme.secondary.copy(.12f))))) {
        Column(Modifier.fillMaxSize().padding(24.dp),verticalArrangement=Arrangement.Center,horizontalAlignment=Alignment.CenterHorizontally) {
            AnimatedVisibility(true, enter=slideInVertically()+fadeIn()) {
                Column(horizontalAlignment=Alignment.CenterHorizontally) {
                    Box(Modifier.size(78.dp).clip(RoundedCornerShape(24.dp)).background(MaterialTheme.colorScheme.primary),contentAlignment=Alignment.Center){ Text("R",fontSize=38.sp,fontWeight=FontWeight.Black,color=Color.White) }
                    Spacer(Modifier.height(14.dp)); Text("RIVAN CSC Manager",fontSize=26.sp,fontWeight=FontWeight.Bold); Text("Digital Seva • 100 CSC Network",color=MaterialTheme.colorScheme.onSurfaceVariant)
                    Spacer(Modifier.height(28.dp))
                    Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){ RoleChip("Admin",role=="admin"){role="admin";id="ADMIN-01"}; RoleChip("Operator",role=="operator"){role="operator";id="OP-001"} }
                    Spacer(Modifier.height(16.dp))
                    OutlinedTextField(id,{id=it},label={Text("Login ID")},singleLine=true,modifier=Modifier.fillMaxWidth())
                    Spacer(Modifier.height(10.dp)); OutlinedTextField(pass,{pass=it},label={Text("Password")},singleLine=true,modifier=Modifier.fillMaxWidth())
                    if(error.isNotBlank()){ Spacer(Modifier.height(8.dp)); Text(error,color=MaterialTheme.colorScheme.error,fontSize=13.sp) }
                    Spacer(Modifier.height(16.dp)); Button(onClick={ val ok=if(role=="admin") vm.loginAdmin(id,pass) else vm.loginOperator(id,pass)==null; if(!ok) error="Login failed. Check ID/password or approval status."; else Toast.makeText(context,"Welcome to RIVAN CSC Manager",Toast.LENGTH_SHORT).show() },modifier=Modifier.fillMaxWidth().height(52.dp),shape=RoundedCornerShape(16.dp)){ Text("Secure Login",fontWeight=FontWeight.Bold) }
                    Spacer(Modifier.height(12.dp)); Text("Demo Admin: ADMIN-01 / 1234 • Operator: OP-001 / 1234",fontSize=11.sp,color=MaterialTheme.colorScheme.onSurfaceVariant)
                }
            }
        }
    }
}

@Composable fun RoleChip(text:String,selected:Boolean,onClick:()->Unit){ Surface(onClick=onClick,modifier=Modifier.weight(1f),shape=RoundedCornerShape(14.dp),color=if(selected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.surfaceVariant){Box(Modifier.padding(12.dp),contentAlignment=Alignment.Center){Text(text,fontWeight=FontWeight.Bold,color=if(selected) Color.White else MaterialTheme.colorScheme.onSurface)}}}
@Composable fun OutlinedTextField(value:String,onValueChange:(String)->Unit,label:@Composable()->Unit,singleLine:Boolean=true,modifier:Modifier=Modifier,placeholder:@Composable()->Unit={}){ androidx.compose.material3.OutlinedTextField(value,onValueChange,label=label,singleLine=singleLine,modifier=modifier,placeholder=placeholder) }

@Composable
fun MainShell(vm:AppViewModel,dark:Boolean,onTheme:(Boolean)->Unit){
    val data by vm.data.collectAsStateWithLifecycle(); var section by rememberSaveable { mutableStateOf(Section.HOME) }; var page by rememberSaveable { mutableStateOf("dashboard") }
    val operator=data.auth.role=="operator"
    Scaffold(bottomBar={ BottomAppBar(containerColor=MaterialTheme.colorScheme.surface){ val items=if(operator) listOf(Section.HOME,Section.WORK,Section.FINANCE,Section.HR,Section.SYSTEM) else listOf(Section.HOME,Section.CENTERS,Section.WORK,Section.FINANCE,Section.HR,Section.SYSTEM); Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.SpaceEvenly){items.forEach{s->NavigationBarItem(selected=section==s,onClick={section=s;page=when(s){Section.HOME->"dashboard";Section.CENTERS->"cscs";Section.WORK->"work";Section.FINANCE->"finance";Section.HR->"hr";Section.SYSTEM->"system"}},icon={Icon(s.icon,null)},label={Text(s.label,fontSize=10.sp)},alwaysShowLabel=true)}} }}) { pad -> Column(Modifier.padding(pad).fillMaxSize()){ TopBar(data,page,onTheme,dark,vm); AnimatedContent(page,label="page"){ p-> PageHost(p,data,vm){page=it} } } }
}

@Composable fun TopBar(data:AppData,page:String,onTheme:(Boolean)->Unit,dark:Boolean,vm:AppViewModel){ Row(Modifier.fillMaxWidth().padding(horizontal=16.dp,vertical=12.dp),verticalAlignment=Alignment.CenterVertically){ Column(Modifier.weight(1f)){Text(data.branding.appName,fontWeight=FontWeight.Black,fontSize=19.sp); Text(if(data.auth.role=="admin")"Admin • Network Control" else "Operator • ${data.auth.cscId}",fontSize=11.sp,color=MaterialTheme.colorScheme.onSurfaceVariant)} IconButton(onClick={onTheme(!dark)}){Icon(if(dark) Icons.Default.LightMode else Icons.Default.DarkMode,null)} IconButton(onClick={vm::logout}){Icon(Icons.Default.Logout,null)} } }

@Composable
fun PageHost(page:String,data:AppData,vm:AppViewModel,setPage:(String)->Unit){ when(page){
    "dashboard"->Dashboard(data,vm,setPage); "cscs"->CscScreen(data,vm); "operators"->OperatorScreen(data,vm); "customers"->CustomerScreen(data,vm); "services"->ServiceScreen(data,vm); "applications"->ApplicationScreen(data,vm); "work"->WorkHub(data,vm,setPage); "finance"->FinanceScreen(data,vm); "payments"->PaymentsScreen(data); "requests"->RequestsScreen(data,vm); "attendance"->AttendanceScreen(data,vm); "leaves"->LeaveScreen(data,vm); "payroll"->PayrollScreen(data,vm); "documents"->DocumentScreen(data,vm); "reports"->ReportsScreen(data); "notifications"->NotificationScreen(data,vm); "system"->SystemHub(data,vm,setPage); "branding"->BrandingScreen(data,vm); "security"->SecurityScreen(data,vm); "profile"->ProfileScreen(data,vm); else->Dashboard(data,vm,setPage)
} }

@Composable
fun Dashboard(data:AppData,vm:AppViewModel,setPage:(String)->Unit){
    val scope=data.auth.cscId; val apps=data.applications.filter{scope=="ALL"||it.cscId==scope}; val income=data.incomes.filter{scope=="ALL"||it.cscId==scope}.sumOf{it.amount}; val exp=data.expenses.filter{scope=="ALL"||it.cscId==scope}.sumOf{it.amount}; val pending=data.requests.count{it.status=="Pending"};
    LazyColumn(Modifier.fillMaxSize().padding(horizontal=16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){ item{Spacer(Modifier.height(4.dp)); Text("Good ${greet()} 👋",fontSize=24.sp,fontWeight=FontWeight.Black); Text("Your CSC operations at a glance",color=MaterialTheme.colorScheme.onSurfaceVariant)}; item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(10.dp)){MetricCard("Applications",apps.size.toString(),Icons.Default.Description,Modifier.weight(1f));MetricCard("Income","₹${money(income)}",Icons.Default.TrendingUp,Modifier.weight(1f));MetricCard("Expenses","₹${money(exp)}",Icons.Default.TrendingDown,Modifier.weight(1f))}}; item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(10.dp)){MetricCard("Profit","₹${money(income-exp)}",Icons.Default.AccountBalanceWallet,Modifier.weight(1f));MetricCard("Pending","$pending",Icons.Default.PendingActions,Modifier.weight(1f))}}; item{SectionTitle("Quick Actions")}; item{QuickGrid(listOf("New Customer" to "customers","New Application" to "applications","Attendance" to "attendance","Payment" to "payments","Refund Request" to "requests","Reports" to "reports"),setPage)}; item{SectionTitle("Recent Applications")}; items(apps.take(5),key={it.id}){AppRow(it)}; item{Spacer(Modifier.height(20.dp))}}
}

