@Composable fun PayrollScreen(data:AppData,vm:AppViewModel){var show by remember{mutableStateOf(false)};ListScreen("Salary / Payroll",data.payrolls.size,{show=true},"Create Payroll"){LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){items(data.payrolls){p->Card(shape=RoundedCornerShape(16.dp)){Column(Modifier.padding(14.dp)){Row{Text(p.operatorName,Modifier.weight(1f),fontWeight=FontWeight.Bold);StatusPill(p.status)};Text("${p.month} • Net ₹${money(p.net)}",fontSize=12.sp);Text("Basic ₹${money(p.basic)} + Bonus ₹${money(p.bonus)} − Deduction ₹${money(p.deduction)} − Advance ₹${money(p.advance)}",fontSize=11.sp,color=MaterialTheme.colorScheme.onSurfaceVariant);if(p.status!="Paid")TextButton({vm.markPayrollPaid(p.id)}){Text("Mark Paid")}}}}}};if(show)PayrollForm(data.operators){p->vm.addPayroll(p);show=false}}

@Composable fun DocumentScreen(data:AppData,vm:AppViewModel){var show by remember{mutableStateOf(false)};ListScreen("Document Vault",data.documents.size,{show=true},"Add Document"){LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){items(data.documents){d->Card(shape=RoundedCornerShape(16.dp)){Column(Modifier.padding(14.dp)){Text(d.customerName,fontWeight=FontWeight.Bold);Text("${d.service} • ${d.docType}",fontSize=12.sp);Text("Expiry: ${d.expiry.ifBlank{"Not set"}} • ${d.version}",fontSize=11.sp,color=MaterialTheme.colorScheme.onSurfaceVariant)}}}}};if(show)DocumentForm(data.customers){d->vm.addDocument(d);show=false}}

@Composable fun ReportsScreen(data:AppData){val ctx=LocalContext.current;Column(Modifier.fillMaxSize().padding(16.dp)){Text("Reports & Export",fontSize=23.sp,fontWeight=FontWeight.Black);Spacer(Modifier.height(12.dp));val income=data.incomes.sumOf{it.amount};val expense=data.expenses.sumOf{it.amount};ReportCard("Applications",data.applications.size.toString());ReportCard("Customers",data.customers.size.toString());ReportCard("Income","₹${money(income)}");ReportCard("Expense","₹${money(expense)}");ReportCard("Profit","₹${money(income-expense)}");Spacer(Modifier.height(12.dp));Button(onClick={val text=buildCsv(data);val i=Intent(Intent.ACTION_SEND).apply{type="text/csv";putExtra(Intent.EXTRA_TEXT,text)};ctx.startActivity(Intent.createChooser(i,"Export CSV"))},modifier=Modifier.fillMaxWidth()){Text("Export CSV")};Spacer(Modifier.height(8.dp));Text("Phase 3 report layer is local/offline. Online scheduled reports are reserved for Phase 4.",fontSize=11.sp,color=MaterialTheme.colorScheme.onSurfaceVariant)}}
