@Composable fun BrandingScreen(data:AppData,vm:AppViewModel){var name by remember(data.branding){mutableStateOf(data.branding.appName)};var tag by remember(data.branding){mutableStateOf(data.branding.tagline)};var color by remember(data.branding){mutableStateOf(data.branding.primary)};var theme by remember(data.branding){mutableStateOf(data.branding.theme)};Column(Modifier.fillMaxSize().padding(16.dp)){Text("Branding",fontSize=23.sp,fontWeight=FontWeight.Black);Spacer(Modifier.height(12.dp));OutlinedTextField(name,{name=it},label={Text("App Name")},modifier=Modifier.fillMaxWidth());Spacer(Modifier.height(8.dp));OutlinedTextField(tag,{tag=it},label={Text("Tagline")},modifier=Modifier.fillMaxWidth());Spacer(Modifier.height(8.dp));OutlinedTextField(color,{color=it},label={Text("Primary Color HEX")},modifier=Modifier.fillMaxWidth());Spacer(Modifier.height(8.dp));Text("Theme");Row{FilterChip(theme=="light",{theme="light"},{Text("Light")});Spacer(Modifier.width(8.dp));FilterChip(theme=="dark",{theme="dark"},{Text("Dark")})};Spacer(Modifier.height(14.dp));Button({vm.saveBranding(Branding(name,tag,color,theme,data.branding.footer))},modifier=Modifier.fillMaxWidth()){Text("Save Branding")}}}

@Composable fun SecurityScreen(data:AppData,vm:AppViewModel){val ctx=LocalContext.current;val export=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/octet-stream")){uri->if(uri!=null)ctx.contentResolver.openOutputStream(uri)?.use{it.write(vm.exportBytes())}};val import=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){uri->if(uri!=null){ctx.contentResolver.openInputStream(uri)?.use{vm.importBytes(it.readBytes())}}};Column(Modifier.fillMaxSize().padding(16.dp)){Text("Security & Backup",fontSize=23.sp,fontWeight=FontWeight.Black);Spacer(Modifier.height(12.dp));InfoCard("Local storage","App data is stored on this device. Phase 4 will add server/cloud sync.");Button({vm.snapshot()},modifier=Modifier.fillMaxWidth()){Text("Create Local Snapshot")};Spacer(Modifier.height(8.dp));Button({export.launch("RIVAN_CSC_Backup.bin")},modifier=Modifier.fillMaxWidth()){Text("Export Backup File")};Spacer(Modifier.height(8.dp));Button({import.launch(arrayOf("application/octet-stream","application/*","*/*"))},modifier=Modifier.fillMaxWidth()){Text("Import Backup File")};Spacer(Modifier.height(8.dp));TextButton({vm.resetDemo()}){Text("Reset Demo Data",color=MaterialTheme.colorScheme.error)};Spacer(Modifier.height(12.dp));Text("Recent audit logs",fontWeight=FontWeight.Bold);LazyColumn{items(data.auditLogs.take(12)){a->Text("${a.time} • ${a.action} • ${a.detail}",fontSize=11.sp,modifier=Modifier.padding(vertical=4.dp))}}}}
