fun today()=SimpleDateFormat("yyyy-MM-dd",Locale.US).format(Date())
fun greet()=when(Calendar.getInstance().get(Calendar.HOUR_OF_DAY)){in 5..11->"Morning";in 12..16->"Afternoon";else->"Evening"}
fun money(v:Double)=String.format(Locale.US,"%.0f",v)
fun buildCsv(d:AppData):String{val sb=StringBuilder();sb.append("Application ID,Customer,Service,Amount,Payment,Status,Date\n");d.applications.forEach{sb.append("${it.id},${it.customerName},${it.serviceName},${it.amount},${it.paymentMode},${it.status},${it.date}\n")};return sb.toString()}
